import{z as h,x as s,o as r,c as p,q as i,j as t,D as e,d as o,s as E,S as n}from"./chunks/framework.C8m1ZpeB.js";const I=JSON.parse('{"title":"瑞利判据笔记（Mack）","description":"","frontmatter":{"title":"瑞利判据笔记（Mack）","date":"2026-09-07T00:00:00.000Z","section":"litho"},"headers":[],"relativePath":"litho/rayleigh-litho-note.md","filePath":"litho/rayleigh-litho-note.md","lastUpdated":1791063341000}'),A={name:"litho/rayleigh-litho-note.md"};function m(B,a,d,c,_,S){const l=s("Mermaid");return r(),p("div",null,[a[2]||(a[2]=i('<h1 id="瑞利判据笔记-mack" tabindex="-1">瑞利判据笔记（Mack） <a class="header-anchor" href="#瑞利判据笔记-mack" aria-label="Permalink to &quot;瑞利判据笔记（Mack）&quot;">​</a></h1><div class="epigraph"><p>光学教材里的瑞利两针孔，给出的是「刚能分开两个艾里斑」；产线要的是在剂量、焦距与胶对比都合格时能稳定印出的线宽。Mack 把后者写成带 k₁ 的工程式，并用图像对数斜率去谈工艺窗，而不是只报一个分辨距。</p><footer>—— Rayleigh 1879 的两源分辨讨论；Chris A. Mack, Fundamental Principles of Optical Lithography, Wiley, 2007</footer></div><p>本篇是光刻栏附录链的第一篇，主干课程到此收束。主干里的<a href="/litho/rayleigh-litho">瑞利判据：CD = k₁ λ / NA</a>已经钉过产线公式、三个旋钮与单次曝光的 \\(k_1\\) 地板；<a href="/litho/nils-ils">NILS 与 ILS</a>已经把对数斜率的定义与读法写完。附录不重抄这两课，只做文献对照，补三件主干没有的事：0.61 判据的来路、Mack 书里从 NILS 走到窗口的推导线索、以及原书的章节脉络。附录链下一站是 <a href="/litho/asml-euv-high-na">ASML EUV / High-NA 产品线</a>。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>0.61 不是从光刻里长出来的，把它当 \\(k_1\\) 的下限是文献史上的张冠李戴。这条线值得按年代读一遍。</p>',5)),(r(),t(n,null,{default:e(()=>[E(l,{id:"mermaid-13",class:"mermaid",graph:"flowchart%20LR%0A%20%20AIRY%5B%22Airy%201835%3Cbr%2F%3E%E5%9C%86%E5%AD%94%E8%A1%8D%E5%B0%84%E6%96%91%E7%AC%AC%E4%B8%80%E9%9B%B6%E7%82%B9%22%5D%20--%3E%20ABBE%5B%22Abbe%201873%3Cbr%2F%3E%E7%9B%B8%E5%B9%B2%E5%8D%8A%E8%8A%82%E8%B7%9D%E6%9E%81%E9%99%90%22%5D%0A%20%20ABBE%20--%3E%20RAY%5B%22Rayleigh%201879%3Cbr%2F%3E%E4%B8%A4%E7%82%B9%E9%9D%9E%E7%9B%B8%E5%B9%B2%E5%88%A4%E6%8D%AE%22%5D%0A%20%20RAY%20--%3E%20SPAR%5B%22Sparrow%201916%3Cbr%2F%3E%E6%8B%90%E7%82%B9%E5%B9%B6%E5%90%88%22%5D%0A%20%20SPAR%20--%3E%20K1%5B%221980%E2%80%9390%20%E5%B9%B4%E4%BB%A3%E4%BA%A7%E7%BA%BF%3Cbr%2F%3Ek%E2%82%81%20%E6%89%93%E5%8C%85%E7%B3%BB%E6%95%B0%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[o(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=i('<p>Airy（1835）算出圆孔衍射斑的第一零点在 \\(1.22\\,\\lambda/D\\)，对物方半角即 \\(0.61\\,\\lambda/\\mathrm{NA}\\)。这只是几何，还不是判据。Abbe（1873）把显微镜成像写成衍射级的收集：相干照明的周期物，半节距极限是 \\(\\lambda/(2\\mathrm{NA})\\)，口语常作 \\(0.5\\lambda/\\mathrm{NA}\\)；数值孔径作为镜头设计量在这里登场。Rayleigh（1879，<em>Philosophical Magazine</em>，副题即「面向光谱仪」）提出两点判据：两个非相干点像，一个的中央极大落在另一个的第一极小上，合成剖面刚好有一个可辨的凹陷——\\(0.61\\lambda/\\mathrm{NA}\\) 由此成为「刚能分开」的代称。Sparrow（1916）改用拐点并合来定分辨：两像剖面刚不出现下凹的位置。那已经是「边还陡不陡」的思路，与半世纪后 NILS 的取向遥遥相望。</p><p>半导体产业接手的不是这条判据，而是另一条惯例：1980–90 年代的产线语言与教材（Levinson 一脉）把工程打包系数写成 \\(k_1\\)，路线图用 \\(k_1\\) 报进度。0.61 与 \\(k_1\\) 只共享一个字母——前者是 Airy 斑第一零点的几何常数，后者是照明、掩模、胶与计算光刻的打包。</p><p><span class="marginnote">直觉类比：0.61 回答的是「两颗星刚能看成两颗」（视力表），\\(k_1\\) 回答的是「这条线在产量与良率约束下印不印得出来」（工厂验收标准）。视力表再准，也代替不了产线的合格线——两把尺量程与接收器都不同。</span></p><h3 id="判据的接收器不同" tabindex="-1">判据的接收器不同 <a class="header-anchor" href="#判据的接收器不同" aria-label="Permalink to &quot;判据的接收器不同&quot;">​</a></h3><p>光谱学的接收器是眼睛或探测器，问「两根线分不分开」；晶圆厂的接收器是胶加显影，问「线宽在不在公差里，离焦偏剂量后还在不在」。判据史读清楚，就知道两边的数不可互换：把 0.61 写进晶圆厂，等于拿光谱仪的验收单去收线宽的货。</p><p><span class="marginnote">Rayleigh 的 1879 原文动机是光谱双线的分辨，判据对象是点像；阿贝路线处理的是相干周期物。两条线在教科书里常被捏成一句「分辨极限」，各自的适用面并不同。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>Mack 书里从 NILS 定义走到工艺窗，中间有小信号的一步，主干<a href="/litho/exposure-latitude">曝光宽容度</a>与<a href="/litho/ed-process-window">曝光–散焦工艺窗口</a>两课给出完整窗口账；这里只留推导线索。</p><p>阈值条件是 \\(I(x_e)\\,E=I_\\mathrm{th}\\)：剂量 \\(E\\) 变 \\(1+\\epsilon\\)，等效于空中像整体乘同一因子，边从 \\(x_e\\) 挪到 \\(x_e+\\Delta x_e\\)。两边取对数微分：</p> \\[\\frac{d\\ln I}{dx}\\Big|_{x_e}\\Delta x_e=-\\Delta\\ln E \\quad\\Longrightarrow\\quad \\Delta x_e=-\\frac{w}{\\mathrm{NILS}}\\,\\Delta\\ln E, \\]<p>其中 \\(w\\) 是目标线宽（NILS 的归一化宽度，定义见 <a href="/litho/nils-ils">NILS 与 ILS</a>）。倒过来读，就是曝光宽容度的小信号估计：</p> \\[|\\Delta\\ln E|\\approx \\mathrm{NILS}\\cdot\\frac{|\\Delta x_e|}{w}. \\]<p>数量级一眼可读：NILS \\(=3\\)、\\(w=40\\,\\mathrm{nm}\\)、允许 \\(\\pm 2\\,\\mathrm{nm}\\)，单边剂量窗约 \\(1.7\\%\\)。书里就用这条小信号式把空中像的几何接到 E–D 窗的记账；孔、线端与不对称照明各自换 \\(w\\) 与最险的那条边。</p><p><span class="marginnote">再代一组数感受 NILS 的杠杆：\\(w=20\\,\\mathrm{nm}\\)、NILS \\(=4\\)、允许 \\(\\pm 1.5\\,\\mathrm{nm}\\)，单边剂量窗 \\(\\approx 1.5/20/4 \\approx 1.9\\%\\)。同样的线宽公差，NILS 每翻一倍，剂量窗也跟着翻倍——这就是全栏把 NILS 当硬通货的原因。</span></p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>Mack 原书（<em>Fundamental Principles of Optical Lithography</em>, 2007）的章节行进，按主题可以收成一条四段的前向链，这也是本栏主干课程排布的对照系：</p><ul><li><strong>成像</strong>：先把空中像写成部分相干强度计算——Hopkins 核与源点叠加，评价对象是 \\(I(x,y)\\) 本身（Hopkins 原文的对照见附录 <a href="/litho/hopkins-1953-paper">Hopkins 部分相干成像</a>）。</li><li><strong>评价</strong>：把「分辨率」从单一分辨距换到边缘陡度——ILS、NILS、对比度，再装进 E–D 窗与聚焦–剂量预算。NILS 在这一段首次成为接口符号。</li><li><strong>记录</strong>：进胶——光化学反应、驻波与摆动曲线、PEB 与扩散，把光学 NILS 折算成潜像对比。</li><li><strong>控制</strong>：把窗口接回产线——套刻、产能、良率与工艺控制，判据从这里交还工程。</li></ul><p>读原书的要点是：<strong>NILS 是贯穿接口，不是某一节的孤立定义</strong>。成像部分引入它，窗口部分反复调用它，记录部分把它折给化学，控制部分拿它当工艺的验收量。抓住这条接口，四段就不是四个孤立专题；对照阅读时，<a href="/litho/goodman-fourier-optics">Goodman 傅里叶光学</a>给频域工具，<a href="/litho/levinson-litho-book">Levinson 光刻原理</a>给产线工程语境，Mack 居中做成像到窗口的桥。</p>',18)),(r(),t(n,null,{default:e(()=>[E(l,{id:"mermaid-83",class:"mermaid",graph:"flowchart%20TD%0A%20%20IMG%5B%22%E6%88%90%E5%83%8F%EF%BC%9AHopkins%20%E7%A9%BA%E4%B8%AD%E5%83%8F%22%5D%20--%3E%20EVAL%5B%22%E8%AF%84%E4%BB%B7%EF%BC%9AILS%20%2F%20NILS%20%2F%20%E5%AF%B9%E6%AF%94%E5%BA%A6%22%5D%0A%20%20EVAL%20--%3E%20WIN%5B%22E-D%20%E7%AA%97%20%2F%20%E8%81%9A%E7%84%A6-%E5%89%82%E9%87%8F%E9%A2%84%E7%AE%97%22%5D%0A%20%20WIN%20--%3E%20REC%5B%22%E8%AE%B0%E5%BD%95%EF%BC%9A%E8%83%B6%E5%8C%96%E5%AD%A6%20%C2%B7%20PEB%20%C2%B7%20%E6%89%A9%E6%95%A3%22%5D%0A%20%20REC%20--%3E%20CTL%5B%22%E6%8E%A7%E5%88%B6%EF%BC%9A%E5%A5%97%E5%88%BB%20%C2%B7%20%E4%BA%A7%E8%83%BD%20%C2%B7%20%E8%89%AF%E7%8E%87%22%5D%0A%20%20NILS%5B%22NILS%EF%BC%9A%E8%B4%AF%E7%A9%BF%E6%8E%A5%E5%8F%A3%22%5D%20-.-%3E%20IMG%0A%20%20NILS%20-.-%3E%20EVAL%0A%20%20NILS%20-.-%3E%20REC%0A%20%20NILS%20-.-%3E%20CTL%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[o(" Loading... ",-1)])]),_:1})),a[4]||(a[4]=i('<p><span class="marginnote">术语翻译：NILS（归一化图像对数斜率）就是给「空中像的边有多陡」打的归一化分数——边越陡，同样的线宽公差能换来越大的剂量窗。Mack 书里它是成像、评价、记录、控制四段共用的接口，所以抓 NILS 一条线就能把全书串起来。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本篇是文献对照，不替代主干的推导。引书按主题回溯，不逐字抄目录编号与页码，防止把转述写成原文。0.61 属于两点非相干判据，Sparrow 判据也不是产线标准，两者都不该出现在工艺规格里。小信号式只在阈值附近线性区可用：NILS 本身随离焦与剂量变，扫到窗口边沿要回到 E–D 的完整账。不给未公开的某代机台 \\(k_1\\) 内部表——那条规矩主干已立，附录只守不重申。</p><p><span class="marginnote">出处：G. B. Airy, 1835；E. Abbe, 1873；Lord Rayleigh, <em>Phil. Mag.</em> 1879；C. M. Sparrow, 1916；C. A. Mack, <em>Fundamental Principles of Optical Lithography</em>, Wiley, 2007。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>0.61 的文献链：Airy 1835 几何 → Abbe 1873 相干半节距 → Rayleigh 1879 两点判据 → Sparrow 1916 拐点判据；半导体 \\(k_1\\) 是 1980–90 年代另一条产线惯例，与 0.61 不可互换。</li><li>NILS 推导线索：阈值边条件对剂量取对数微分，\\(\\Delta x_e=(w/\\mathrm{NILS})\\,\\Delta\\ln E\\)；曝光宽容度与 NILS 同向，完整窗口账在主干 E–D 课。</li><li>Mack 原书按「成像 → 评价 → 记录 → 控制」行进，NILS 是贯穿四段的接口符号。</li><li>出处：Airy；Abbe；Rayleigh；Sparrow；Mack 2007。</li></ul>',6))])}const N=h(A,[["render",m]]);export{I as __pageData,N as default};
